insert into steinhart_monsters (name, challenge_rating, creature_type, book_page, summary) values
  ('Охотник в Вуали', '7', 'Аберрация', 380, 'Падший охотник-друид, сросшийся с деревьями: атаки на дистанции, тюрьма из корней, телепорт между деревьями, маска даёт сопротивление магии.'),
  ('Извращённый Библиотекарь', '11', 'Нежить', 382, 'Призрачный заклинатель-некромант (остеомантия), левитирует, аура тишины, отражает заклинания, при 0 хитов раз в день восстанавливает все хиты и часть ячеек.'),
  ('Тисифона, Первозданный Хаос', '14', 'Аберрация', 384, 'Друид-мутант из Круга Симбиоза: регенерация, легендарные действия, при 0 хитов уходит в неуязвимую сферу и возрождается.'),
  ('Малах, Ангел Плоти', '15', 'Конструкт', 386, 'Механический "ангел" в облачении из плоти убитых: ядовитые миазмы, легендарные действия, форма и способности меняются при полу-хитах.'),
  ('Король Охоты', '28', 'Гуманоид и Аберрация', 397, 'Финальный босс Падших Охотников — бессмертный воин (не теряет сознание при 0 хитов), иммунитет к немагическому физическому урону, скорость не замедлить.')
insert into steinhart_items (name, category, rarity, book_page, summary) values
  ('Проклятие Лунной Крови', 'Потусторонний орнамент', 'редкая/оч.редкая/легендарная (зависит от способа нанесения)', 258, 'Превращает владельца в багряного зверя (Луннокровного) при определённых условиях — тема каннибализма/проклятия первых жертв Бедствия.'),
  ('Свинцовая Кровь', 'Потусторонний орнамент', 'варьируется', 260, 'Связан с состоянием берсерка: при завершении эффекта хиты падают до 0 и теряются все силы орнамента на неделю.'),
  ('Жертвенное Клеймо', 'Потусторонний орнамент', 'варьируется', 260, 'Получают воскрешённые Кровавой Луной Перерождения — помечает их как связанных с ней, усиливается во время её действия.'),
  ('Потомок Молнии', 'Потусторонний орнамент', 'варьируется', 261, 'Электрическая тема — см. книгу для точных эффектов по уровням нанесения (рисунок/татуировка/шрамирование).'),
  ('Благословение Навре', 'Потусторонний орнамент', 'варьируется', 263, 'См. книгу для точных эффектов.'),
  ('Мефитовая Печать', 'Потусторонний орнамент', 'варьируется', 263, 'Связан с ядовитыми/газовыми эффектами (мефит) — см. книгу для точных эффектов.'),
  ('Первый Орнамент', 'Потусторонний орнамент', 'варьируется', 264, 'Часть трилогии Первый/Второй/Третий Орнамент, тема праведного мстителя с "Клинком серафима".'),
  ('Второй Орнамент', 'Потусторонний орнамент', 'варьируется', 264, 'Продолжение линейки — усиливает Праведное возмездие и позволяет слить Клинок серафима с оружием.'),
  ('Третий Орнамент', 'Потусторонний орнамент', 'варьируется', 264, 'Финальная ступень линейки орнаментов серафима — см. книгу для точных эффектов.')
insert into steinhart_items (name, category, rarity, book_page, summary) values
  ('Освященная Пушка', 'Огнестрельное оружие (пушка)', 'необычная', 212, 'Раз за ход можно заменить атаку мощным залпом по линии 120×5 футов.'),
  ('Большая Берта', 'Огнестрельное оружие (пушка)', 'редкая', 213, 'Инкрустирована лунным золотом, бонусным действием заряжает следующий выстрел одним из трёх стихийных эффектов.'),
  ('Сумка для Пушечных Ядер', 'Чудесный предмет', 'необычная', 206, 'Вмещает до 100 пушечных ядер почти без веса.'),
  ('Дамасцена', 'Чудесный предмет', 'необычная', 206, 'Устройство Потомков: конус синего пламени из свинцовых пуль.'),
  ('Рука Славы', 'Чудесный предмет', 'очень редкая', 207, 'Доп. настройка на кольцо + невидимость, пока горит палец; открывание на объекты в свету.'),
  ('Грибной Чай', 'Чудесный предмет (зелье)', 'варьируется', 207, 'Снимает приступ безумия на час, но нужен спасбросок Телосложения против рвоты (таблица по цвету чая).'),
  ('Святой Тоник', 'Зелье', 'необычное', 208, 'Лечит 4d4+4 хитов и болезни, но со скрытыми от игроков побочками безумия/проклятия при злоупотреблении.'),
  ('Позолоченное Луной Оружие', 'Апгрейд оружия', '—', 214, 'Покрытие оружия лунным золотом: +1d4 урона против негуманоидов, преим. на спасброски от испуга/безумия, истирается за 3 месяца.'),
insert into steinhart_monsters (name, challenge_rating, creature_type, book_page, summary) values
  ('Паразитический Дух', '1/4', 'Нежить', 310, 'Бестелесная парящая голова-призрак, присасывается усиками и питается жизнью жертвы, уязвима к солнечному свету.'),
  ('Падший Луярнец', '1/2', 'Зверь и Гуманоид', 311, 'Низкоуровневый одичавший падший, атакует стаей вместе с сородичами и носит факел.'),
  ('Житель-Демонический Ворон', '1', 'Зверь и Гуманоид', 312, 'Искажённая падалью воронья тварь, не способная летать высоко, подражает голосам и звукам, чтобы запутать.'),
  ('Дух', '1', 'Нежить', 313, 'Призрак, переключающийся между бесплотной и материальной формой, с разными атаками холодом и ядом для каждой.'),
  ('Модифицированный Пациент', '2', 'Гуманоид', 314, 'Жертва жутких опытов над разумом и телом психиатрической клиники — см. книгу для деталей способностей.'),
  ('Фанатик', '2', 'Гуманоид', 315, 'Рядовой религиозный фанатик-культист с базовым набором боевых и заклинательных способностей.'),
  ('Мясник', '3', 'Гуманоид и Монстр', 316, 'Переродившийся проклятокровый с аберрантным глазом на груди, рассеивающим магию, бьётся тесаком.'),
  ('Ликан Бедствия', '3', 'Зверь и Гуманоид', 317, 'Заражённый ликантропией зверочеловек, порождённый Бедствием.'),
  ('Горгулья-Хранитель', '3', 'Конструкт', 318, 'Каменный страж церкви, притворяется неподвижной статуей, метит цели и даёт союзникам каменную защиту от урона.'),
  ('Охотник', '3', 'Гуманоид', 319, 'Рядовой охотник Луярны: универсальный боец с клинком и огнестрелом, уклоняется от атак рывком.'),
  ('Бритвеннолезвенная Бродяга', '3', 'Конструкт', 320, 'Собака-конструкт из плоти и металла Потомков, хватает укусом, а вращающаяся пила ранит того, кто её держит.'),
  ('Крикокрыл', '3', 'Зверь и Гуманоид', 321, 'Летучий искажённый зверь с эхолокацией, оглушающий целую область мощным криком.'),
  ('Похититель', '4', 'Аберрация и Гуманоид', 322, 'Проклятокровый похититель людей, прячет пленённых жертв внутри собственного тела.'),
  ('Медведь-Ревенант', '4', 'Зверь и Нежить', 323, 'Медведь-нежить, искалеченный кислотой, хватает челюстью и сопротивляется немагическому дробящему урону.'),
  ('Повелитель Огоньков', '5', 'Нежить', 324, 'Предводитель блуждающих огоньков, призывает и телепатически командует мелкими огоньками-вассалами.'),
  ('Отверженная Гончая', '5', 'Зверь и Аберрация', 326, 'Многоглазая гончая-аберрация с пятью щупальцами, способная удерживать в захвате сразу несколько целей.'),
  ('Опаленный Арбитр', '5', 'Аберрация', 328, 'Гуманоид-убийца на службе Исследователей заката, вырывает урон прямо из души и телепортируется для добивания.'),
  ('Мимолётная Туманность', '6', 'Монстр', 330, 'Летающее существо с собственным гравитационным полем, колдует и телепортируется, избегая приближения.'),
  ('Дуллахан', '6', 'Нежить', 331, 'Безголовый всадник-нежить Круга Симбиоза с хлещущим позвоночником и способностью подчинять взглядом своей отрубленной головы.'),
  ('Живая Артиллерия', '6', 'Аберрация и Гуманоид', 334, 'Аберрантная ходячая пушка на ложноножках-щупальцах, при смерти детонирует нестабильное тело.'),
  ('Кошмарная Сороконожка', '6', 'Аберрация', 336, 'Роевая многоножка из единого улья, усиливается числом сородичей поблизости и плюётся кислотой конусом.'),
  ('Крадущаяся Тень', '6', 'Исчадие (Монстр)', 337, 'Крылатая тень-исчадие, вырывающая органы критическим попаданием и дышащая смертоносной некротической энергией.'),
  ('Страшилище', '7', 'Аберрация', 338, 'Иллюзорный кошмар, облик которого отражает худшие страхи смотрящего на него; пугает взглядом и колдует.'),
  ('Ночной Призрак', '7', 'Аберрация', 340, 'Безликая тварь, питающаяся эмоциями спящих жертв, парализует и оглушает хвостом, невидима при неосторожности.'),
  ('Заточенная Дева', '8', 'Аберрация и Нежить', 342, 'Остеомант-нежить, заглатывающая жертв целиком и выпускающая костяные шипы, обращающие в камень.'),
  ('Прикованный Великан', '8', 'Великан', 343, 'Великан, искалеченный опытами над разумом, скован цепями, которыми сбивает противников с ног.'),
  ('Полый Страж', '8', 'Конструкт (и Гуманоид)', 346, 'Антимагический конструкт-страж с мифриловым костяком, снимает временные хиты и рушит концентрацию врагов.'),
  ('Егерь', '8', 'Гуманоид', 348, 'Элитный охотник-гуманоид, наносящий клинком незаживающие кровоточащие раны, быстрый и уклончивый.'),
  ('Лунный Ревенант', '8', 'Нежить', 349, 'Безмолвный скелетный мститель, невидимый вне лунного света, наводит ужас по области и телепортируется.'),
  ('Ревущая Грива', '8', 'Зверь и Элементаль', 351, 'Подземный лев-элементаль, копающий тоннели; оглушающий рёв сбивает с ног и замедляет противников.'),
  ('Хранитель Голубого Пламени', '9', 'Конструкт', 352, 'Доспех-конструкт Потомков с лазурным пламенем, резко усиливающийся при критически низких хитах.'),
  ('Сумрачный Червус', '9', 'Монстр', 354, 'Бестелесная тень-паразит, укусом ворует максимум хитов жертвы и создаёт теневых миньонов из свежих трупов.'),
  ('Белуа Пожиратель', '10', 'Монстр', 356, 'Свирепый зверь-пожиратель: критические укусы отрывают части тела жертвы, впадает в неистовую ярость.'),
  ('Совомед', '10', 'Монстр', 357, 'Гротескная химера из совы, медведя и змеи, хватает вытянутой шеей и щупальцем, яростно реагирует на урон излучением.'),
  ('Кающийся', '10', 'Гуманоид и Монстр', 360, 'Улейный разум в золотых масках, ворует себе конечности жертв и запирает существ в "богохульной тюрьме".'),
  ('Гальванизированный Хищник', '11', 'Зверь (и Монстр)', 362, 'Химера Потомков, заряженная электричеством: поглощает урон электричеством вместо вреда и телепортируется.'),
  ('Смерть', '12', 'Нежить', 364, 'Нежить, способная сменить облик на любого гуманоида или зверя её уровня опасности; пугает "Свистом смерти".'),
  ('Малый Аватар Грезящего', '12', 'Аберрация', 365, 'Неподвижный аватар потустороннего бога, заставляет цели повторять свои действия и насылает ауру страха.'),
  ('Похищающая Души Аранея', '13', 'Монстр', 368, 'Паучий похититель душ, поглощает души мёртвых для усиления и имитирует голоса поглощённых жертв.'),
  ('Эктеллакс, Освежеванный', '17', 'Аберрация и Дракон', 371, 'Взрослый потусторонний дракон — пугающее присутствие, дыхание пустотой и холодом, меняется местами с целью заклинанием.'),
  ('Орр, Скорбное Возрождение (Первая Форма)', '18', 'Аберрация (бог)', 372, 'Первая форма божества-аберрации: крик причиняет длящуюся боль, при падении до 0 хитов перерождается во вторую форму.'),
  ('Орр, Скорбное Возрождение (Вторая Форма)', '20', 'Аберрация (бог)', 375, 'Вторая, ледяная форма Орра — замедляет холодом и призывает подвластных ледяных охотников-прислужников.'),
  ('Аватар Матери-Козы', '22', 'Аберрация', 378, 'Богиня-аберрация с кругами перерождения: насылает стакающиеся проклятия и призывает подконтрольных монстров.'),
  ('Викарий Присцилла', '15', 'Гуманоид', 388, 'Соратница Штейнхардта в охотах — жрица-воительница с клинком лунного света и божественными заклинаниями.'),
  ('Абаддон, Несостоявшийся Страж', '16', 'Небожитель', 390, 'Безумный падший небожитель Лучезарной церкви с заразительным гневом и щупальцем, притягивающим врагов к себе.'),
  ('Лучезарный Наблюдатель', '17', 'Гуманоид и Аберрация', 392, 'Звёздный гуманоид-аберрация, покрывает землю ослепляющей смолой и бьёт по области звёздной сверхновой.'),
  ('Герхард, Проклятый Рыцарь', '18', 'Небожитель и Гуманоид', 394, 'Проклятый рыцарь, переключающийся между гуманоидной и звериной стойками с разным набором атак в каждой.')
